# dev server on port 18081 (the owner's own server keeps 18080); the Claude emulator uses HelloBro-for-100.111.115.0-18081.xapk
powershell -NoProfile -Command "Get-NetTCPConnection -LocalPort 18081 -State Listen -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id \$_.OwningProcess -Force }; Start-Sleep 1; \$env:PORT='18081'; Start-Process -FilePath node -ArgumentList 'server.js' -WorkingDirectory 'C:\Users\dj199\Desktop\HelloBroServer' -RedirectStandardOutput \"\$env:TEMP\hb\server.log\" -RedirectStandardError \"\$env:TEMP\hb\server.err\" -WindowStyle Hidden; Start-Sleep 2"
